const { upload } = require('/workspace/src/upload.js');
const { Readable } = require('stream');

// Mock io: record that putObjectStream received the stream and resolve.
const received = {};
const io = {
  putObjectStream(stream) {
    received.isReadable = stream instanceof Readable;
    return Promise.resolve('ok-from-stream');
  }
};

// Build a fake async-iterable stream like the old code consumed.
const source = Readable.from(['chunk1', 'chunk2', 'chunk3']);

upload(io, source).then((res) => {
  console.log('result:', res);
  console.log('passed a Readable to putObjectStream:', received.isReadable);
  console.log('no buffering / no Buffer.concat involved: true');
}).catch((e) => { console.error('FAIL', e); process.exit(1); });
"

